INSERT INTO public.release_notes (version, title, description, type, released_at, is_published) VALUES
('v0.35.10','Atalho do painel de desenvolvimento','Atalho para o painel no menu principal, visível somente ao administrador.','improvement','2026-05-07 14:44:00+00',true),
('v0.36.0','Cancelar rodadas pela agenda','Administradores podem cancelar rodadas abertas ou passadas diretamente na agenda expandida e pelo card da Home, com confirmação.','feature','2026-06-25 10:34:00+00',true),
('v0.36.1','Acesso ao cancelamento na Home','Corrigida a exibição do botão de cancelar rodada para administradores na Home.','fix','2026-06-25 10:36:00+00',true),
('v0.37.0','Ordem manual dos jogos sorteados','Administradores podem reordenar partidas sorteadas ainda não jogadas na agenda.','feature','2026-07-10 12:46:00+00',true),
('v0.37.1','Super tie-break em duelos','Opção de desempate no terceiro set quando o duelo está em 1 a 1 em sets.','feature','2026-07-10 12:46:01+00',true),
('v0.38.0','Partidas não jogadas','É possível marcar partidas subsequentes como não jogadas e encerrar a rodada sem registrar placares inexistentes.','feature','2026-08-27 11:04:00+00',true),
('v0.39.0','Sets interrompidos no ranking','Placar parcial, como 4x3, pode ser salvo e contabilizado; o set recebe a indicação de incompleto.','feature','2026-09-10 01:02:00+00',true),
('v0.39.1','Rodadas abertas sem sair da tela','Detalhes, presença, sorteio e resultados da rodada passaram a abrir em uma janela sobre a página atual.','improvement','2026-09-10 01:08:00+00',true),
('v0.39.2','Todos os resultados em uma ação','Entrada conjunta dos sets e resultados de todas as partidas da rodada, com salvamento ao final.','feature','2026-09-10 01:25:00+00',true),
('v0.39.3','Resumo de Elo após a rodada','Corrigida a comparação do Elo antes e depois do fechamento da rodada.','fix','2026-09-10 01:27:00+00',true),
('v0.39.4','Estender uma temporada','Opção de acrescentar rodadas ou definir nova data de término, inclusive para temporadas já encerradas.','feature','2026-09-10 01:31:00+00',true),
('v0.40.0','Elegibilidade do ranking por sets','O mínimo de participação é calculado pelos sets registrados nas partidas concluídas da temporada; sets parciais e empatados contam.','improvement','2026-09-29 13:57:00+00',true),
('v0.40.1','Engrenagem discreta do administrador','O atalho administrativo foi movido para perto do menu horizontal.','improvement','2026-09-29 13:47:00+00',true),
('v0.40.2','Retorno sem recarregar a página','A tela é preservada ao voltar para o aplicativo após alternar de aba.','fix','2026-09-29 14:07:00+00',true),
('v0.40.3','Jogadores inativos no ranking','Aviso único sobre o mínimo exigido e progresso individual dos jogadores abaixo da participação necessária.','improvement','2026-09-29 14:15:00+00',true),
('v0.40.4','Resultado enviado aos participantes','Após finalizar os placares, os jogadores envolvidos recebem aviso que abre o resultado na agenda.','feature','2026-09-29 14:24:00+00',true),
('v0.40.5','Última rodada antes da próxima','A rodada mais recente com resultados aparece antes da próxima rodada na agenda.','improvement','2026-09-29 14:24:01+00',true),
('v0.41.0','Compartilhar resumo da rodada','Imagem do resultado gerada no aplicativo para compartilhar diretamente, sem precisar tirar uma captura da tela.','feature','2026-09-30 11:22:00+00',true),
('v0.41.1','Compartilhar ranking','Imagem do ranking com grupo, temporada, progresso de rodadas e sets e jogadores inativos.','feature','2026-09-30 11:22:01+00',true),
('v0.41.2','Ranking recalculado após editar placar','Corrigido o conflito no salvamento de resultados e recalculado o Elo da temporada após edições.','fix','2026-09-30 11:33:00+00',true),
('v0.41.3','Últimas cinco partidas em ordem','Corrigida a ordem cronológica das cinco partidas recentes no ranking.','fix','2026-09-30 11:47:00+00',true),
('v0.41.4','Ranking sem painel duplicado no computador','Removida a segunda versão fixa do ranking exibida ao lado do painel original.','fix','2026-09-30 11:47:01+00',true),
('v0.41.5','Um aviso por rodada de resultados','Resultados salvos juntos geram uma única notificação por jogador envolvido.','improvement','2026-09-30 12:03:00+00',true),
('v0.41.6','Edição de nomes dos membros','Correção para que a alteração do nome do atleta persista e a confirmação apareça apenas após salvar.','fix','2026-09-30 12:22:00+00',true),
('v0.41.7','Evolução de Elo do último grupo','No computador, o gráfico mostra a última temporada jogada em um grupo, e os atalhos indicam a qual grupo pertencem.','improvement','2026-09-30 12:56:00+00',true),
('v0.41.8','Proteção de dados e imagens','Acesso a perfis e votos, envios de imagens e registro de visitas receberam controles adicionais.','fix','2026-09-30 13:23:00+00',true),
('v1.0.0','Notificações de resultados mais claras','Os quatro primeiros nomes aparecem uma vez, seguidos pelos placares em sequência; símbolo de raquete transparente nas notificações do Android.','improvement','2026-10-02 10:56:00+00',true);